import type { Metadata } from 'next'
import { Inter } from 'next/font/google'
import './globals.css'

const inter = Inter({ subsets: ['latin'] })

export const metadata: Metadata = {
  title: 'My Blog',
  description: 'A complex blog application',
}

export default function RootLayout({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <html lang="en">
      <body className={inter.className}>
        <div className="app-container">
          <header>
            <h1>My Blog</h1>
            <nav>
              <a href="/">Home</a>
              <a href="/blog">Blog</a>
            </nav>
          </header>
          <main>
            {children}
          </main>
          <footer>
            <p>&copy; 2024 My Blog</p>
          </footer>
        </div>
      </body>
    </html>
  )
}

import { Metadata } from 'next'
import Link from 'next/link'
import { headers } from 'next/headers'

interface Post {
  id: number
  title: string
  body: string
}

export const metadata: Metadata = {
  title: 'Home - My Blog',
  description: 'Welcome to my blog homepage',
  openGraph: {
    title: 'Home - My Blog',
  },
}

export default async function HomePage() {
  const headersList = headers()
  const userAgent = headersList.get('user-agent') || ''

  const posts: Post[] = await fetch('https://jsonplaceholder.typicode.com/posts?_limit=5')
    .then(res => res.json())

  const timestamp = new Date().toISOString()

  return (
    <>
      <div>
        <h1>Welcome to My Blog</h1>
        <p>Server-side rendered at: {timestamp}</p>
        <p>Your user agent: {userAgent}</p>

        <h2>Recent Posts</h2>
        <ul>
          {posts.map(post => (
            <li key={post.id}>
              <Link href={`/blog/${post.id}`}>{post.title}</Link>
            </li>
          ))}
        </ul>

        <Link href="/blog">
          View All Posts
        </Link>
      </div>
    </>
  )
}

