import { Metadata } from 'next'
import Link from 'next/link'

interface Post {
  id: number
  title: string
  body: string
}

export const metadata: Metadata = {
  title: 'Blog - My Blog',
  description: 'All blog posts',
}

export default async function BlogIndex() {
  const posts: Post[] = await fetch('https://jsonplaceholder.typicode.com/posts')
    .then(res => res.json())

  return (
    <>
      <div>
        <h1>All Blog Posts</h1>

        <div className="posts-grid">
          {posts.map(post => (
            <div key={post.id} className="post-card">
              <h2>
                <Link href={`/blog/${post.id}`}>{post.title}</Link>
              </h2>
              <p>{post.body.substring(0, 100)}...</p>
              <Link href={`/blog/${post.id}`}>
                Read More
              </Link>
            </div>
          ))}
        </div>
      </div>
    </>
  )
}

import { Metadata } from 'next'
import Link from 'next/link'
import { notFound } from 'next/navigation'

interface Post {
  id: number
  title: string
  body: string
}

interface Comment {
  id: number
  name: string
  email: string
  body: string
}

export async function generateMetadata({ params }: { params: { id: string } }): Promise<Metadata> {
  try {
    const post: Post = await fetch(`https://jsonplaceholder.typicode.com/posts/${params.id}`)
      .then(res => res.json())

    return {
      title: `${post.title} - My Blog`,
      description: post.body.substring(0, 160),
      openGraph: {
        title: post.title,
        description: post.body.substring(0, 160),
      },
    }
  } catch (error) {
    return {
      title: 'Post Not Found - My Blog',
      description: 'The requested post could not be found',
    }
  }
}

export default async function BlogPost({ params }: { params: { id: string } }) {
  try {
    const [post, comments]: [Post, Comment[]] = await Promise.all([
      fetch(`https://jsonplaceholder.typicode.com/posts/${params.id}`).then(res => res.json()),
      fetch(`https://jsonplaceholder.typicode.com/posts/${params.id}/comments`).then(res => res.json())
    ])

    return (
      <>
        <article>
          <Link href="/blog">← Back</Link>

          <h1>{post.title}</h1>
          <p>{post.body}</p>

          <h2>Comments ({comments.length})</h2>
          <div className="comments">
            {comments.map(comment => (
              <div key={comment.id} className="comment">
                <h3>{comment.name}</h3>
                <p>{comment.body}</p>
                <small>By: {comment.email}</small>
              </div>
            ))}
          </div>
        </article>
      </>
    )
  } catch (error) {
    notFound()
  }
}

import { NextResponse } from 'next/server'
import { NextRequest } from 'next/server'

interface Post {
  id: number
  title: string
  content: string
  createdAt?: string
}

export async function GET() {
  // Simulate fetching posts
  const posts: Post[] = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' }
  ]

  return NextResponse.json(posts)
}

export async function POST(request: NextRequest) {
  const { title, content } = await request.json()

  if (!title || !content) {
    return NextResponse.json({ error: 'Title and content are required' }, { status: 400 })
  }

  // Simulate creating a post
  const newPost: Post = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString()
  }

  return NextResponse.json(newPost, { status: 201 })
}

import { NextResponse } from 'next/server'
import { NextRequest } from 'next/server'

interface Post {
  id: number
  title: string
  content: string
  createdAt?: string
  updatedAt?: string
}

export async function GET(
  request: NextRequest,
  { params }: { params: { id: string } }
) {
  const id = params.id

  // Simulate fetching a single post
  const post: Post = {
    id: parseInt(id),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString()
  }

  return NextResponse.json(post)
}

export async function PUT(
  request: NextRequest,
  { params }: { params: { id: string } }
) {
  const id = params.id
  const { title, content } = await request.json()

  // Simulate updating a post
  const updatedPost: Post = {
    id: parseInt(id),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString()
  }

  return NextResponse.json(updatedPost)
}

export async function DELETE(
  request: NextRequest,
  { params }: { params: { id: string } }
) {
  const id = params.id

  // Simulate deleting a post
  return NextResponse.json({ message: `Post ${id} deleted successfully` })
}

