/* Global styles */
body {
  font-family: 'Inter', sans-serif;
  margin: 0;
  padding: 0;
  line-height: 1.6;
}

.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 20px;
}

header {
  background: #f8f9fa;
  padding: 20px 0;
  border-bottom: 1px solid #e9ecef;
  margin-bottom: 30px;
}

header h1 {
  margin: 0;
  font-size: 24px;
}

nav {
  margin-top: 10px;
}

nav a {
  margin-right: 15px;
  text-decoration: none;
  color: #0070f3;
}

main {
  min-height: calc(100vh - 200px);
}

footer {
  margin-top: 50px;
  padding: 20px 0;
  border-top: 1px solid #e9ecef;
  text-align: center;
}

.posts-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 20px;
  margin-top: 30px;
}

.post-card {
  border: 1px solid #e9ecef;
  padding: 20px;
  border-radius: 8px;
}

.post-card h2 {
  margin-top: 0;
}

.comments {
  margin-top: 30px;
}

.comment {
  border: 1px solid #e9ecef;
  padding: 15px;
  margin-bottom: 15px;
  border-radius: 4px;
}

.error-page {
  text-align: center;
  padding: 50px 0;
}

button, a {
  background: #0070f3;
  color: white;
  padding: 10px 20px;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  text-decoration: none;
  display: inline-block;
  margin-top: 20px;
}

button:hover, a:hover {
  background: #0061d6;
}

